() => {
  // Try to scroll the nutrition facts into view
  const btn = document.getElementById('mm-recipes-details__nutrition-link_1-0');
  if (btn) {
    btn.click();
    return 'Clicked nutrition link';
  }
  // Try to find nutrition facts section by ID
  const section = document.querySelector('[id*="nutrition"]');
  if (section) {
    section.scrollIntoView();
    return 'Scrolled to nutrition section';
  }
  return 'No nutrition section found';
}

() => {
  // Find the nutrition facts section
  const allText = document.body.innerText;
  // Look for the nutrition block by ID
  const nutritionSection = document.querySelector('[id*="nutrition"]');

  // Get the full text near "Nutrition Facts"
  const idx = allText.indexOf('Nutrition Facts');
  if (idx >= 0) {
    return allText.substring(idx, idx + 2000);
  }
  return 'Nutrition Facts not found in text. URL: ' + window.location.href;
}

() => {
  // Find and click the nutrition link button
  const btn = document.getElementById('mm-recipes-details__nutrition-link_1-0');
  if (btn) {
    // Get its position
    const rect = btn.getBoundingClientRect();
    btn.click();
    return { clicked: true, rect: {top: rect.top, left: rect.left, width: rect.width, height: rect.height}, text: btn.textContent };
  }
  return { clicked: false };
}

() => {
  // Find the nutrition facts section and get its content
  const allElements = document.querySelectorAll('section, div');
  const results = [];

  for (const el of allElements) {
    if (el.id && el.id.toLowerCase().includes('nutrition')) {
      results.push({id: el.id, text: el.innerText.substring(0, 2000)});
    }
  }

  // Also try by class
  for (const el of document.querySelectorAll('[class*="nutrition" i]')) {
    results.push({class: el.className, id: el.id, text: el.innerText ? el.innerText.substring(0, 1500) : ''});
  }

  return results;
}

() => {
  // Get the full text content of the page
  return document.body.innerText.substring(0, 8000);
}

() => {
  // Get full text and key markers
  const text = document.body.innerText;
  const checks = {
    has155Reviews: text.includes('155 Reviews'),
    hasLowCarb: text.includes('low-carb breakfast'),
    hasTitle: text.includes('Creamy Cottage Cheese Scrambled Eggs'),
    hasCarbs2g: text.includes('Total Carbohydrate 2g'),
    hasFiber0g: text.includes('Dietary Fiber 0g'),
    hasSugars1g: text.includes('Total Sugars 1g'),
    hasProtein16g: text.includes('Protein 16g'),
    hasTotalFat17g: text.includes('Total Fat 17g'),
    hasSatFat8g: text.includes('Saturated Fat 8g'),
    hasChol392mg: text.includes('Cholesterol 392mg'),
    hasSodium295mg: text.includes('Sodium 295mg'),
    hasCalories224: text.includes('Calories224'),
    hasServings2: text.includes('Servings Per Recipe2'),
    url: window.location.href
  };
  return checks;
}

() => {
  // Get the canonical URL or current URL
  const link = document.querySelector('link[rel="canonical"]');
  const ogUrl = document.querySelector('meta[property="og:url"]');
  return {
    canonical: link ? link.href : null,
    ogUrl: ogUrl ? ogUrl.content : null,
    location: window.location.href
  };
}

() => {
  // Add a visible element with the URL text
  const div = document.createElement('div');
  div.id = 'url-marker';
  div.style.position = 'fixed';
  div.style.top = '0';
  div.style.left = '0';
  div.style.zIndex = '999999';
  div.style.background = 'white';
  div.style.padding = '5px';
  div.textContent = window.location.href;
  document.body.prepend(div);
  return window.location.href;
}

() => {
  // Get the recipe link from the page
  const link = document.getElementById('mntl-card-list-card--extendable_1-0');
  if (link) {
    // Display the URL in the link text for now
    const url = link.href;
    const span = document.createElement('span');
    span.id = 'recipe-url-marker';
    span.textContent = ' RECIPE_URL: ' + url + ' ';
    document.body.prepend(span);
    return url;
  }
  return 'no link found';
}

() => {
  const link = document.getElementById('mntl-card-list-card--extendable_1-0');
  if (link && link.href) {
    const url = link.href;
    const div = document.createElement('div');
    div.id = 'recipe-url-marker';
    div.setAttribute('data-recipe-url', url);
    div.textContent = url;
    document.body.appendChild(div);
    return {url: url, found: true};
  }
  return {url: null, found: false};
}

() => {
  // Find all text on page that might contain the URL
  const allText = document.body.innerText;
  const matches = [];
  const regex = /https?:\/\/[^\s]+/g;
  let m;
  while ((m = regex.exec(allText)) !== null) {
    matches.push(m[0]);
  }
  return matches.slice(0, 10);
}

() => {
  // Inject a clearly visible URL marker
  const banner = document.createElement('div');
  banner.id = 'url-banner';
  banner.style.cssText = 'position:fixed;top:0;left:0;width:100%;background:yellow;z-index:99999;padding:10px;font-size:14px;';
  banner.textContent = 'PAGE_URL_HERE: ' + window.location.href + ' END_URL';
  document.body.insertBefore(banner, document.body.firstChild);

  // Also add to a search result link
  const link = document.getElementById('mntl-card-list-card--extendable_1-0');
  if (link && link.href) {
    const urlSpan = document.createElement('span');
    urlSpan.id = 'recipe-link-url';
    urlSpan.textContent = ' ' + link.href + ' ';
    link.appendChild(urlSpan);
  }
  return 'done';
}

() => {
  // Get the URL from various sources
  const result = {
    location: window.location.href,
    canonical: document.querySelector('link[rel="canonical"]')?.href,
    ogUrl: document.querySelector('meta[property="og:url"]')?.content,
  };

  // Also try to find the URL in any text on the page
  const allText = document.body.innerHTML;
  const urlMatch = allText.match(/https?:\/\/[^"'\s<>]+241160[^"'\s<>]*/);
  if (urlMatch) {
    result.foundUrl = urlMatch[0];
  }

  return result;
}
